<div id="timerOverlay" class="tov"><div class="tov-inner"><div class="tov-eyebrow" id="tEyebrow">Pour timer</div><div class="tov-ring-wrap"><svg class="tov-ring" viewBox="0 0 240 240"><circle class="tov-ring-bg" cx="120" cy="120" r="108"/><circle class="tov-ring-fg" id="tRing" cx="120" cy="120" r="108"/></svg><div class="tov-ring-center"><div class="tov-state" id="tState">POUR</div><div class="tov-time" id="tTime">0:00</div><div class="tov-target" id="tTarget"></div></div></div><div class="tov-note" id="tNote"></div><div class="tov-next" id="tNext"></div><div class="tov-steps" id="tSteps"></div><div class="tov-ctrls"><button id="tPause" class="tov-btn">Pause</button><button id="tSkip" class="tov-btn">Skip</button><button id="tReset" class="tov-btn">Reset</button><button id="tClose" class="tov-btn tov-close">Close</button></div></div></div>
<script>
var APP_VERSION="2.2.0";
// To enable update checks: set this to the raw URL of version.json in your repo,
// e.g. "https://raw.githubusercontent.com/USER/REPO/main/version.json". Leave "" to disable.
var VERSION_URL="https://raw.githubusercontent.com/amalwahieb/coffee-Way-Standard/main/version.json";
var REPO_URL="https://github.com/amalwahieb/coffee-Way-Standard";
var FILE_URL="https://github.com/amalwahieb/coffee-Way-Standard/blob/main/Coffee%20Way%20Standard.scriptable";

// ============ ENGINE (identical to the app) ============
const ROASTS=[{id:"light",label:"Light",temp:99,grind:"Medium-fine",notch:-2,agit:"high",bloomMult:2.2,rest:[10,24]},{id:"med-light",label:"Med-Light",temp:96,grind:"Medium-fine",notch:-1,agit:"high",bloomMult:2.1,rest:[8,21]},{id:"medium",label:"Medium",temp:93,grind:"Medium",notch:0,agit:"medium",bloomMult:2.0,rest:[6,18]},{id:"med-dark",label:"Med-Dark",temp:90,grind:"Medium-coarse",notch:1,agit:"low",bloomMult:2.0,rest:[4,14]},{id:"dark",label:"Dark",temp:88,grind:"Coarse",notch:2,agit:"low",bloomMult:2.0,rest:[3,10]}];
const PROCESSES=[{id:"washed",label:"Washed",flavor:"clean, bright, articulate cup",tweak:"Brew straight for clarity.",degas:0},{id:"honey",label:"Honey",flavor:"rounder sweetness with light fruit",tweak:"Standard pours; sweetness sits in the middle.",degas:2},{id:"natural",label:"Natural",flavor:"fruit-forward, heavy, sometimes boozy",tweak:"Gentler pours — the bed is fragile and degasses fast.",degas:5},{id:"anaerobic",label:"Anaerobic",flavor:"intense, funky, fermented character",tweak:"Pull it back: cooler or coarser so the funk doesn't dominate.",degas:5},{id:"coferment",label:"Co-fermented / Infused",flavor:"loud added aromatics riding over the base coffee",tweak:"Keep it cool and gentle — added aromatics turn harsh fast.",degas:5},{id:"wethulled",label:"Wet-hulled (Sumatra)",flavor:"earthy, herbal, heavy body, low acidity",tweak:"Body over brightness — standard pours; expect a slow, muddy-looking bed.",degas:2},{id:"decaf",label:"Decaf (any method)",flavor:"softer, rounder version of the bean",tweak:"Porous beans extract fast — brewed cooler; go coarser before anything else if bitter.",degas:0}];
const STRENGTHS=[{id:"light",label:"Lighter",ratio:17.0},{id:"balanced",label:"Balanced",ratio:16.67},{id:"strong",label:"Stronger",ratio:15.5}];
const GOALS=[{id:"everyday",label:"Everyday Balanced",method:"everyday"},{id:"brighter",label:"Fruity · Kasuya 4:6",method:"fourSix"},{id:"sweeter",label:"Sweeter · Kasuya 4:6",method:"fourSix"},{id:"classic",label:"Classic · Hoffmann",method:"hoffmann"},{id:"osamah",label:"Osamah Alawwam · Roasting House owner",method:"osamah",grindOff:-3,tempOff:1}];
const ORIGINS=[{id:"ethiopia",label:"Ethiopia",notes:"jasmine, citrus, stone fruit, tea-like body",tip:"Aromatics are delicate — don't over-agitate; let the floral top notes survive."},{id:"kenya",label:"Kenya",notes:"blackcurrant, tomato, syrupy body, vivid acidity",tip:"Can take a slightly finer grind to pull more of that blackcurrant depth.",notch:-1},{id:"colombia",label:"Colombia",notes:"caramel, red apple, balanced sweetness",tip:"Forgiving and balanced — a great bag to benchmark your dial-in on."},{id:"peru",label:"Peru",notes:"mild chocolate, nuts, caramel, soft citrus, gentle acidity",tip:"Soft and forgiving — a clean, balanced everyday cup; often organic and washed."},{id:"brazil",label:"Brazil",notes:"chocolate, peanut, heavy body, low acidity",tip:"Dense, low-acid flavour; keep temp moderate or it turns ashy.",temp:-1},{id:"guatemala",label:"Guatemala",notes:"cocoa, orange, structured acidity"},{id:"costa-rica",label:"Costa Rica",notes:"honeyed sweetness, citrus, clean finish"},{id:"rwanda",label:"Rwanda / Burundi",notes:"red fruit, floral, silky"},{id:"panama",label:"Panama Gesha",notes:"jasmine, bergamot, tropical — delicate & rare",tip:"Treat it gently: low agitation, clean even pours. Don't bully a Gesha."},{id:"yemen",label:"Yemen",notes:"wild, boozy, dried fruit, warm spice"},{id:"saudi",label:"Saudi Arabia (Khawlani)",notes:"dried fruit, dark chocolate, spice, winey, full body",tip:"Jazan Khawlani is usually natural-processed and heritage-grown — treat like a rich natural: gentle pours, and don't over-extract the spice."},{id:"indonesia",label:"Indonesia / Sumatra",notes:"earthy, herbal, cedar, big body, low acidity",tip:"Usually roasted darker — lean coarser and cooler with gentle pours.",notch:1,temp:-1},{id:"vietnam",label:"Vietnam",notes:"dark chocolate, roasted nut, cocoa bitterness, heavy body, very low acidity",tip:"Usually robusta — bold and low-acid, and it turns bitter easily. Grind coarser, brew cooler, and pour gently. Specialty Vietnamese arabica (from Da Lat) is milder — treat it more like a regular origin.",notch:1,temp:-1},{id:"honduras",label:"Honduras",notes:"caramel, stone fruit, mild"},{id:"el-salvador",label:"El Salvador",notes:"chocolate, red apple, soft"},{id:"tanzania",label:"Tanzania / Uganda",notes:"blackcurrant, bright, juicy"},{id:"thailand",label:"Thailand",notes:"mild, sweet, chocolate-nut, gentle fruit"},{id:"mexico",label:"Mexico",notes:"nutty, gentle citrus, light body"},{id:"india",label:"India",notes:"spice, cedar, low acidity (often monsooned)"},{id:"other",label:"Single — other / unsure",notes:"follow the descriptors printed on the bag"}];
const BLENDS=[{id:"filter",label:"Filter / pour-over blend",notes:"built for clarity across its components",tip:"Designed for this method — brew to the roast on the bag, and keep pours even since mixed densities extract at different rates.",notch:0,temp:0},{id:"espresso",label:"Espresso blend",notes:"usually darker, denser; chocolate & nut",tip:"Roasted for pressure, not pour-over. Go coarser and cooler and pour gently.",notch:1,temp:-1},{id:"house",label:"House / breakfast blend",notes:"comfortable, chocolatey, forgiving",tip:"Easy-going and hard to wreck — a good everyday dial-in.",notch:0,temp:0}];
const GRINDERS=[{id:"comandante",type:"manual",label:"Comandante C40",base:23,step:2,unit:"clicks",min:8,max:40,wf:"40 clicks over the useful range, 12 clicks per turn of the ring (25-30µm each). Count from burr contact."},{id:"com-redclix",type:"manual",label:"Comandante C40 + Red Clix",base:44,step:4,unit:"clicks",min:16,max:80,wf:"Red Clix doubles the resolution: 24 clicks per turn, about 15µm each."},{id:"1z-q2",type:"manual",label:"1Zpresso Q2 / Q-Air",base:26,step:3,unit:"clicks",min:6,max:60,wf:"Internal dial, 30 clicks per rotation, 3 clicks per number (25µm each) — count clicks from zero."},{id:"1z-jxpro",type:"manual",label:"1Zpresso JX-Pro",base:52,step:4,unit:"clicks",min:20,max:140,wf:"Top dial, 40 clicks per rotation, 4 clicks per number (12.5µm each) — count clicks from zero."},{id:"1z-j",type:"manual",label:"1Zpresso J-Max / J-Ultra",base:210,step:10,unit:"clicks",min:60,max:320,wf:"External dial, 90 clicks per rotation, 10 clicks per number (8.8µm each) — count clicks from zero."},{id:"1z-x",type:"manual",label:"1Zpresso X-Pro / X-Ultra",base:55,step:6,unit:"clicks",min:20,max:180,wf:"External dial, 60 clicks per rotation, 6 clicks per number (12.5µm each) — count clicks from zero."},{id:"1z-kmax",type:"manual",label:"1Zpresso K-Max / K-Plus",micro:10,base:7,step:0.3,unit:"",min:0,max:9,wf:"Numbered dial: 10 clicks between each number. Read as number + clicks (e.g. 7 and 2 clicks)."},{id:"1z-zp6",type:"manual",label:"1Zpresso ZP6",micro:10,base:5,step:0.3,unit:"",min:0,max:9,wf:"Pour-over-tuned. Numbered dial: 10 clicks between each number. Read as number + clicks (e.g. 5 and 2 clicks)."},{id:"timemore-c",type:"manual",label:"Timemore Chestnut C2 / C3",base:17,step:2,unit:"clicks",min:8,max:35,wf:"12 clicks per turn, about 32µm each — the same adjustment logic as a Comandante."},{id:"timemore-x",type:"manual",label:"Timemore Chestnut X",base:17,step:1,unit:"",min:1,max:23,wf:"Macro dial numbered 1-23 with a micro ring for fine tuning. Pour-over sits around 15-19 on the macro dial."},{id:"kingrinder",type:"manual",label:"Kingrinder K6 / K4",base:80,step:6,unit:"clicks",min:30,max:150,wf:"External numbered dial — count clicks from burr contact."},{id:"king-k2",type:"manual",label:"Kingrinder K0 / K1 / K2",base:50,step:5,unit:"clicks",min:20,max:90,wf:"External dial — count clicks from burr contact."},{id:"kinu",type:"manual",label:"Kinu M47",stepless:true,baseDesc:"around the filter mark on the gauge",wf:"Stepless. Owners count turns from burr contact — pour-over sits around 3 turns, espresso closer to 1.5."},{id:"ode1",type:"electric",label:"Fellow Ode Gen 1",micro:3,base:4,step:0.334,unit:"",min:1,max:11,wf:"Dial 1-11 with two clicks between each number (31 steps). Gen 1 cuts coarser than Gen 2 at the same number."},{id:"ode2",type:"electric",label:"Fellow Ode Gen 2",micro:3,base:5,step:0.334,unit:"",min:1,max:11,wf:"Dial 1-11 with two clicks between each number (31 steps), read as 5, 5·1, 5·2, then 6. Single-dose, very low retention."},{id:"opus",type:"electric",label:"Fellow Opus",micro:4,base:6,step:0.5,unit:"",min:1,max:11,wf:"Dial 1-11 with three clicks between each number (41 settings). Wider range than the Ode."},{id:"encore",type:"electric",label:"Baratza Encore",base:15,step:1,unit:"",min:1,max:40,wf:"Stepped collar, 40 numbered settings (0 finest to 40 coarsest). Baratza puts V60 at 15."},{id:"encore-esp",type:"electric",label:"Baratza Encore ESP",base:23,step:1,unit:"",min:1,max:40,wf:"40 steps, but the fine half of the dial is given over to espresso, so filter settings sit higher than on the Encore."},{id:"virtuoso",type:"electric",label:"Baratza Virtuoso+",base:15,step:1,unit:"",min:1,max:40,wf:"Same 40-step collar as the Encore with better burrs. Baratza puts V60 at 15."},{id:"sette",type:"electric",label:"Baratza Sette 270",base:16,step:0.5,unit:"",min:1,max:30,wf:"30 macro settings with 9 micro positions between each (270 in total). Baratza puts V60 at macro 16.",micro:9},{id:"sculptor",type:"electric",label:"Timemore Sculptor 064",base:9,step:0.5,unit:"",min:1,max:14,wf:"Stepped dial, 36 settings in the pour-over configuration. The 064S is stepless instead - use the stepless entry for that one."},{id:"sculptor78",type:"electric",label:"Timemore Sculptor 078",base:9,step:0.5,unit:"",min:1,max:14,wf:"Stepped dial you can feel clicking. Documented pour-over sits around 7-12. The 078S is stepless instead."},{id:"sculptor-s",type:"electric",label:"Timemore Sculptor 064S / 078S",stepless:true,baseDesc:"the middle of the dial, then move in tiny amounts",wf:"Stepless - the dial turns smoothly with no clicks. Very small moves change a lot."},{id:"niche",type:"electric",label:"Niche Zero",base:40,step:3,unit:"",min:0,max:70,wf:"Stepless collar with numbers as a guide. Espresso sits around 10-18, V60 around 35-45, French press 55-65."},{id:"df64",type:"electric",label:"DF64 / DF54",stepless:true,baseDesc:"just coarser than your espresso point",wf:"Single-dose, stepless — set by reference. RDT helps with static."},{id:"sd40",type:"electric",label:"Turin SD40",stepless:true,baseDesc:"just coarser than your espresso point",wf:"Single-dose, stepless — set by reference. RDT helps with static."},{id:"lagom",type:"electric",label:"Option-O Lagom",stepless:true,baseDesc:"around your filter reference",wf:"Stepless single-doser — log a reference number per coffee."},{id:"varia-vs3",type:"electric",label:"Varia VS3",stepless:true,baseDesc:"around the filter zone of the dial",wf:"Stepless single-doser — log a reference number per coffee."},{id:"eureka",type:"electric",label:"Eureka Mignon",stepless:true,baseDesc:"the filter end of the worm dial",wf:"Stepless and geared fine — make small moves."},{id:"sgp",type:"electric",label:"Breville Smart Grinder Pro",base:24,step:2,unit:"",min:1,max:60,wf:"60 stepped settings across the dial; filter sits in the middle of the range."},{id:"wilfa",type:"electric",label:"Wilfa Uniform / Svart",base:22,step:2,unit:"",min:1,max:41,wf:"41 stepped settings from espresso through to steeping. Wilfa puts espresso near 5."},{id:"x54",type:"electric",label:"Mahlkönig X54",base:6.5,step:0.5,unit:"",min:1,max:10,wf:"Stepless adjustment with a printed scale — the number is a guide, not a detent."},{id:"ek43",type:"electric",label:"Mahlkönig EK43 (café)",base:8.5,step:1,unit:"",min:1,max:16,wf:"Cafe grinder, stepless with a printed scale. Small moves change a lot."},{id:"oxo",type:"electric",label:"OXO Brew Conical",base:8,step:1,unit:"",min:1,max:15,wf:"15 stepped settings. Documented V60 sits at 8."},{id:"xbloom",type:"electric",label:"xBloom Studio (built-in)",base:36,step:3,unit:"",min:1,max:80,wf:"Built into the machine: 80 settings from 1 (espresso, about 180µm) to 80 (cold brew, about 1050µm), 18.75µm apart. Filter work sits around 30-45."}];
const BREWERS=[{id:"v60",label:"V60",kind:"pour",tempOff:0,grindOff:0,ratioMul:1,finishAdd:0,note:"Conical and fast-flowing — the all-rounder, clarity-forward.",maxDose:60},{id:"kalita",label:"Kalita Wave",kind:"pour",tempOff:0,grindOff:0,ratioMul:1,finishAdd:15,note:"Flat bed with three small holes — forgiving and even. Pour in gentle pulses, keeping the water level low.",maxDose:45},{id:"chemex",label:"Chemex",kind:"pour",tempOff:1,grindOff:1,ratioMul:1,finishAdd:45,note:"Thick filter slows the flow and adds clarity — grind a touch coarser and run water a touch hotter.",maxDose:90},{id:"aeropress",label:"AeroPress",kind:"immersion",tempOff:-3,grindOff:-1,ratioMul:0.85,finishAdd:0,note:"Immersion then press: short contact, finer grind, less water. Cooler water suits it.",maxDose:42},{id:"switch",label:"Switch",kind:"immersion",tempOff:0,grindOff:1,ratioMul:1,finishAdd:0,note:"Immersion–dripper hybrid: steep with the valve closed, then open to release. A coarser grind suits the steep.",maxDose:30}];
const fmt=(s)=>Math.floor(s/60)+":"+String(Math.round(s%60)).padStart(2,"0");
const cToF=(c)=>Math.round((c*9)/5+32);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function freshnessVerdict(days,rest,degas){const min=Math.max(2,rest[0]-Math.round(degas/2)),max=rest[1]-Math.round(degas/2);if(days<min)return{id:"fresh",min,max};if(days<=max)return{id:"ideal",min,max};if(days<=max+45)return{id:"aging",min,max};return{id:"stale",min,max}}
function gsTasteBtns(which){
  var opts=[["sour",P("Sour / weak","حامض / ضعيف")],["balanced",P("Balanced ✓","متوازن ✓")],["bitter",P("Bitter / harsh","مر / حاد")]];
  var cur=gsetup[which];
  return '<div class="gso-taste">'+opts.map(function(o){return '<button class="gso-tbtn'+(cur===o[0]?" on":"")+'" data-gstaste="'+which+'|'+o[0]+'">'+o[1]+'</button>';}).join("")+'</div>';
}
function gsetupTestHtml(){
  var u=P(gsetup.unit,({clicks:"نقرات",numbers:"أرقام",rotations:"لفات"})[gsetup.unit]||gsetup.unit);
  var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max);
  var coarseSuggest=Math.round(mn+(mx-mn)*0.7),fineSuggest=Math.round(mn+(mx-mn)*0.4),midSuggest=Math.round(mn+(mx-mn)*0.55);
  if(gsetup.depth==="thorough"){
    return '<div class="gso-title">'+P("Brew two cups","حضّر كوبين")+'</div>'
      +'<div class="gso-sub">'+P("Same coffee and recipe both times — only the grind changes. Brew, taste, tap.","نفس القهوة والوصفة في المرتين — الطحن فقط يتغيّر. اطحن، ذوّق، اضغط.")+'</div>'
      +'<div class="gso-brew"><div class="gso-brew-h">'+P("Cup A — coarser","كوب A — أخشن")+'</div><div class="gso-set">'+P("Set your grinder to about ","اضبط مطحنتك على حوالي ")+'<input class="gso-num" data-gsset="coarseSet" inputmode="decimal" min="'+gsetup.min+'" max="'+gsetup.max+'" value="'+(gsetup.coarseSet||coarseSuggest)+'"> '+u+'</div>'+gsTasteBtns("coarseTaste")+'</div>'
      +'<div class="gso-brew"><div class="gso-brew-h">'+P("Cup B — finer","كوب B — أنعم")+'</div><div class="gso-set">'+P("Now set it to about ","الآن اضبطه على حوالي ")+'<input class="gso-num" data-gsset="fineSet" inputmode="decimal" min="'+gsetup.min+'" max="'+gsetup.max+'" value="'+(gsetup.fineSet||fineSuggest)+'"> '+u+'</div>'+gsTasteBtns("fineTaste")+'</div>'
      +'<div class="gso-btns"><button class="gso-ghost" data-gsback="depth">'+P("Back","رجوع")+'</button><button class="gso-primary" data-gsfinish="1">'+P("See my result","أرني النتيجة")+'</button></div>';
  }else{
    return '<div class="gso-title">'+P("Brew one cup","حضّر كوبًا")+'</div>'
      +'<div class="gso-sub">'+P("Brew the recipe, then tell me how it tasted.","حضّر الوصفة، ثم قلّي كيف طعمها.")+'</div>'
      +'<div class="gso-brew"><div class="gso-hintline">'+P("Suggested start: around ","اقتراح للبداية: حوالي ")+midSuggest+' '+u+P(" — but use whatever you brewed."," — لكن استخدم ما حضّرت به فعلًا.")+'</div><div class="gso-set">'+P("What did you set for the test? ","كم "+gsUnitOne()+" وضعت للتجربة؟ ")+'<input class="gso-num" data-gsset="oneSet" inputmode="decimal" min="'+gsetup.min+'" max="'+gsetup.max+'" placeholder="'+midSuggest+'" value="'+(gsetup.oneSet||"")+'"> '+u+'</div>'+gsTasteBtns("oneTaste")+'</div>'
      +'<div class="gso-btns"><button class="gso-ghost" data-gsback="depth">'+P("Back","رجوع")+'</button><button class="gso-primary" data-gsfinish="1">'+P("See my result","أرني النتيجة")+'</button></div>';
  }
}
var MACHINE_MAXDOSE={xbloom:25,aiden:88};
function doseLimit(){var mm=state.machineOn?MACHINE_MAXDOSE[state.machine]:0;if(mm)return mm;var b=BREWERS.find(function(x){return x.id===state.brewer;});return (b&&b.maxDose)?b.maxDose:LIM.dose.max;}
function limOf(k){var l=LIM[k];if(k!=="dose")return l;return{min:l.min,max:doseLimit(),step:l.step,dec:l.dec};}
function gsLimit(unit){return unit==="turns"?15:(unit==="numbers"?100:600);}
function gsClamp(v){var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max);if(isNaN(mn))mn=0;if(isNaN(mx))mx=40;if(isNaN(v))v=(mn+mx)/2;return Math.max(mn,Math.min(mx,v));}
function gsRangeStep(){var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max);if(isNaN(mn))mn=0;if(isNaN(mx))mx=40;var span=Math.max(1,mx-mn);return Math.max(1,Math.round(span*0.15));}
function gsQuickStep(){var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max);if(isNaN(mn))mn=0;if(isNaN(mx))mx=40;var span=Math.max(1,mx-mn);return Math.max(1,Math.round(span*0.10));}
function gsClamp(v){var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max);if(isNaN(mn))mn=0;if(isNaN(mx))mx=40;if(isNaN(v))v=(mn+mx)/2;return Math.max(mn,Math.min(mx,v));}
function gsUnitOne(){return P(({clicks:"click",numbers:"number"})[gsetup.unit]||gsetup.unit,({clicks:"نقرة",numbers:"رقم"})[gsetup.unit]||gsetup.unit);}
function gsUnitLabel(){return P(gsetup.unit==="numbers"?"":gsetup.unit,({clicks:"نقرات",numbers:""})[gsetup.unit]||gsetup.unit);}
function gsShell(body){var o=document.getElementById("gsetupOverlay");o.style.display="";o.innerHTML='<div class="gso-inner">'+body+'</div>';}
function gsFoundScreen(best,note){
  var u=gsUnitLabel();
  gsShell('<div class="gso-title">'+P("Your grind for "+gsetup.name,"طحنتك لـ "+gsetup.name)+'</div>'
    +'<div class="gso-result"><div class="gso-big">'+best+'</div><div class="gso-bigu">'+u+'</div></div>'
    +(note?'<div class="gso-note">'+note+'</div>':"")
    +'<div class="gso-sub">'+P("This is your starting point on this grinder. The app builds every recipe around it, and your brew times fine-tune it over time.","هذي نقطة البداية على هذه المطحنة. التطبيق يبني كل وصفة حولها، وأوقات تحضيرك تضبطها مع الوقت.")+'</div>'
    +'<div class="gso-btns"><button class="gso-ghost" data-gsclose="1">'+P("Cancel","إلغاء")+'</button><button class="gso-primary" data-gssave="1">'+P("Save this grinder","احفظ هذه المطحنة")+'</button></div>');
}
function gsRetryScreen(dir,coarseV,fineV){
  var u=gsUnitLabel();
  var dirTxt=(dir==="finer")?P("Both cups came out under-extracted (sour) — they were too coarse. Your grind is finer than both.","الكوبين طلعوا ناقصين الاستخلاص (حامض) — كانوا خشنين. طحنتك أنعم منهما.")
    :P("Both cups came out over-extracted (bitter) — they were too fine. Your grind is coarser than both.","الكوبين طلعوا زائدي الاستخلاص (مر) — كانوا ناعمين. طحنتك أخشن منهما.");
  gsShell('<div class="gso-title">'+P("Let’s narrow it down","خلّينا نقرّبها")+'</div>'
    +'<div class="gso-sub">'+dirTxt+'</div>'
    +'<div class="gso-brew"><div class="gso-brew-h">'+P("Try this pair next","جرّب هذا الزوج القادم")+'</div><div class="gso-set">'+P("Cup A (coarser): ","كوب A (الأخشن): ")+'<b>'+coarseV+'</b> '+u+' · '+P("Cup B (finer): ","كوب B (الأنعم): ")+'<b>'+fineV+'</b> '+u+'</div></div>'
    +'<div class="gso-btns"><button class="gso-ghost" data-gsclose="1">'+P("Stop here","أوقف هنا")+'</button><button class="gso-primary" data-gsretry="'+coarseV+'|'+fineV+'">'+P("Test this pair","اختبر هذا الزوج")+'</button></div>');
}
function gsClashScreen(){
  gsShell('<div class="gso-title">'+P("These results don’t add up","النتيجتين ما يتفقون")+'</div>'
    +'<div class="gso-sub">'+P("A coarser grind always extracts less than a finer one — so the coarser cup can’t taste more extracted (bitter) than the finer cup. Something else changed between the two brews: pour speed, water temperature, or channeling.","الطحنة الأخشن دائمًا تستخلص أقل من الأنعم — فما يصير الكوب الأخشن يطلع أكثر استخلاصًا (مر) من الأنعم. شيء ثاني اختلف بين التحضيرين: سرعة الصب، حرارة الماء، أو تقنية الصب.")+'</div>'
    +'<div class="gso-note">'+P("Brew the same two settings again, keeping everything else identical — then tap how each tasted.","حضّر نفس الرقمين مرة ثانية مع تثبيت كل شي آخر — ثم اضغط كيف طعم كل واحد.")+'</div>'
    +'<div class="gso-btns"><button class="gso-ghost" data-gsclose="1">'+P("Stop here","أوقف هنا")+'</button><button class="gso-primary" data-gsclear="1">'+P("Taste again","ذوّق مرة ثانية")+'</button></div>');
}
function gsScore(t){return t==="sour"?-1:(t==="bitter"?1:0);}
function gsetupFinish(){
  if(gsetup.depth==="thorough"){
    var s1=parseFloat(gsetup.coarseSet),s2=parseFloat(gsetup.fineSet);
    var t1=gsetup.coarseTaste,t2=gsetup.fineTaste;
    var cS,fS,cT,fT;
    if(s1>=s2){cS=s1;cT=t1;fS=s2;fT=t2;}else{cS=s2;cT=t2;fS=s1;fT=t1;}
    var step=gsRangeStep();
    if(gsScore(cT)>gsScore(fT)){gsetup.best=undefined;gsetup.step="result";gsClashScreen();return;}
    if(cT==="sour"&&fT==="sour"){gsetup.best=undefined;gsetup.step="result";gsRetryScreen("finer",gsClamp(fS-step),gsClamp(fS-step*2));return;}
    if(cT==="bitter"&&fT==="bitter"){gsetup.best=undefined;gsetup.step="result";gsRetryScreen("coarser",gsClamp(cS+step*2),gsClamp(cS+step));return;}
    if(cT==="balanced"&&fT==="balanced"){
      var mid=gsClamp(Math.round((cS+fS)/2*10)/10);gsetup.best=mid;gsetup.step="result";
      var span=parseFloat(gsetup.max)-parseFloat(gsetup.min);var wide=(cS-fS)>Math.abs(span)*0.25;
      gsFoundScreen(mid,wide?P("Both cups tasted good that far apart — this coffee is forgiving, so anywhere in that band works. We took the middle.","الكوبين طلعوا زينين مع الفرق الكبير — هذه القهوة متسامحة، فأي رقم بينهما ينفع. أخذنا المنتصف."):P("Both landed well — we took the middle of the two.","الاثنين طلعوا زينين — أخذنا المنتصف بينهما."));return;
    }
    if(cT==="sour"&&fT==="balanced"){gsetup.best=gsClamp(fS);gsetup.step="result";gsFoundScreen(gsetup.best,"");return;}
    if(cT==="balanced"&&fT==="bitter"){gsetup.best=gsClamp(cS);gsetup.step="result";gsFoundScreen(gsetup.best,"");return;}
    if(cT==="sour"&&fT==="bitter"){gsetup.best=gsClamp(Math.round((cS+fS)/2*10)/10);gsetup.step="result";gsFoundScreen(gsetup.best,P("Your target sits between the two — the coarse cup was under-extracted, the fine one over.","هدفك بين الرقمين — الأخشن ناقص استخلاص والأنعم زائد."));return;}
    gsetup.best=gsClamp(Math.round((cS+fS)/2*10)/10);gsetup.step="result";gsFoundScreen(gsetup.best,"");return;
  }else{
    var v=parseFloat(gsetup.oneSet),t=gsetup.oneTaste,qs=gsQuickStep();
    if(t==="balanced"){gsetup.best=gsClamp(v);gsetup.step="result";gsFoundScreen(gsetup.best,"");return;}
    var nb=(t==="sour")?gsClamp(v-qs):gsClamp(v+qs);gsetup.best=nb;gsetup.step="result";
    gsFoundScreen(nb,(t==="sour")?P("Your cup was under-extracted — try this finer setting. Brew it again to confirm, and adjust from here.","كوبك كان أقل استخلاصه للقهوة، جرّب هذه الدرجة الأنعم. حضّرها مرة ثانية للتأكيد، وعدّل من هنا."):P("Your cup was over-extracted — try this coarser setting. Brew it again to confirm, and adjust from here.","كوبك كان زايد استخلاصه للقهوة، جرّب هذه الدرجة الأخشن. حضّرها مرة ثانية للتأكيد، وعدّل من هنا."));return;
  }
}
function gsetupSave(){
  var mn=parseFloat(gsetup.min),mx=parseFloat(gsetup.max),best=gsetup.best;
  var id="my-"+Date.now();
  // model: base is the midpoint of range mapped so that notch 0 gives roughly the book-medium; we store best as base and a per-notch step
  var range=mx-mn;var _mc=(gsetup.unit!=="turns"&&gsetup.micro>1)?gsetup.micro:0;var step=_mc?Math.round((2/_mc)*1000)/1000:Math.max(0.1,Math.round(range/12*10)/10);
  var g={id:id,type:"manual",label:gsetup.name,base:best,step:step,unit:gsetup.unit==="numbers"?"":gsetup.unit,min:mn,max:mx,custom:true,micro:(gsetup.unit!=="turns"&&gsetup.micro>1)?gsetup.micro:undefined,wf:P("Your calibrated grinder. Trust your dialed number; adjust by taste.","مطحنتك المعايَرة. ثق برقمك؛ عدّل بالذوق.")};
  MYGRINDERS.push(g);state.grinder=id;persist();closeGsetup();renderAll();
}
function openGsetup(){gsetup={step:"basics",name:"",unit:"clicks",min:"",max:"",depth:null,coarseSet:"",coarseTaste:"",fineSet:"",fineTaste:"",oneSet:"",oneTaste:""};renderGsetup();}
