function allGrinders(){return GRINDERS.concat(MYGRINDERS);}
function grinderById(id){return allGrinders().find(function(x){return x.id===id;});}
function grindCalHtml(rec){
  try{
  var g=grinderById(state.grinder);
  if(!g||g.byFeel||g.stepless)return "";
  var off=GRINDOFF[g.id]||0;
  var unit=tr(g.unit||"");
  if(gcalOpen){
    var cur=parseFloat(rec.grindNumber);
    return '<div class="gcal gcal-open"><div class="gcal-q">'+P("This recipe shows ","الوصفة تعطيك ")+'<b>'+rec.grindNumber+'</b>. '+P("What do you actually dial on your "+g.label+"?","ما الرقم الذي تضبطه فعلًا على "+g.label+"؟")+(g.micro?P(" (for a click past a number, type like 9.1 or 9.2)"," (لنقرة بعد رقم، اكتب مثل 9.1 أو 9.2)"):"")+'</div>'
      +'<div class="gcal-row"><input id="gcalInput" class="gcal-input" inputmode="decimal" placeholder="'+rec.grindNumber+'"><button class="gcal-save" data-gcalsave="1">'+P("Save","حفظ")+'</button></div>'
      +'<div class="gcal-hint">'+P("I’ll shift every recipe on this grinder by the difference — coarser or finer, it carries through.","سأزيح كل وصفة على هذه المطحنة بمقدار الفرق — أخشن أو أنعم، يسري على الكل.")+'</div></div>';
  }
  if(off!==0){
    var sign=off>0?"+":"";
    return '<div class="gcal gcal-set"><span class="gcal-badge">'+P("Tuned to your "+g.label,"معايَر لـ "+g.label)+' ('+sign+off+' '+unit+')</span> <button class="gcal-link" data-gcalopen="1">'+P("change","تغيير")+'</button> <button class="gcal-link" data-gcalreset="1">'+P("reset","تصفير")+'</button></div>';
  }
  return '<div class="gcal"><button class="gcal-link" data-gcalopen="1">'+P("Not your number? Tell me what you dial →","مو رقمك؟ قلي وش تضبط فعلًا →")+'</button></div>';
  }catch(e){return "";}
}
function grindPlan(parts){var steps=0,fine=0,why={};function step(name,v){v=v||0;if(v){why[name]=v;steps+=v;}}function unit(name,v){v=v||0;if(v){why[name]=v;fine+=v;}}step("roast",parts.roastNotch);step("origin",parts.originNotch);step("blend",parts.blendNotch);step("brewer",parts.brewerOff);step("style",parts.goalOff);step("freshness",parts.freshNotch);step("your dial-in",parts.manual);unit("dose",parts.doseFine);return{steps:steps,fine:fine,why:why};}
function grindSetting(g,notch,extra){if(!g||g.byFeel)return{mode:"feel"};if(g.stepless)return{mode:"stepless"};var off=(g&&GRINDOFF[g.id])?GRINDOFF[g.id]:0;var v=clamp(g.base+notch*g.step+off+(extra||0),g.min,g.max);if(g.micro){var whole=Math.floor(v);var frac=v-whole;var clicks=Math.round(frac*g.micro);if(clicks>=g.micro){whole+=1;clicks=0;}if(whole>g.max){whole=g.max;clicks=0;}if(whole<g.min){whole=g.min;clicks=0;}var clkWord=(lang==="ar")?"نقرة":("click"+(clicks>1?"s":""));var disp=(clicks===0)?String(whole):(String(whole)+" · "+clicks+" "+clkWord);return{mode:"number",value:disp,numeric:whole+clicks/g.micro,micro:g.micro,offset:off};}var snapped;if(g.step>=1){snapped=Math.round(v);}else{snapped=Math.round(v/g.step)*g.step;snapped=Math.round(snapped*10)/10;}snapped=clamp(snapped,g.min,g.max);snapped=Math.round(snapped*10)/10;return{mode:"number",value:Number.isInteger(snapped)?String(snapped):snapped.toFixed(1),numeric:snapped,offset:off}}
function grindLabel(g,notch,roast,extra){const r=grindSetting(g,notch,extra);if(r.mode==="number")return (r.value+" "+tr(g.unit||"")).trim();if(r.mode==="stepless")return P("Start ","ابدأ من ")+tr(g.baseDesc);return tr(roast.grind)+P(" (by feel)"," (بالتقدير)")}
