function buildSchedule(roast,goal,bloomWater,bloomTime,totalWater,strengthId){const out=[];if(goal.method==="everyday"){var eAfter=totalWater-bloomWater,eStep=eAfter/3;var e1=Math.round(bloomWater+eStep),e2=Math.round(bloomWater+eStep*2);out.push({t:0,label:"Bloom",to:bloomWater,note:P("Wet every ground, then a gentle swirl. Let it breathe.","بلّل كل البن ثم دوّر بهدوء. خلّيها تتنفّس.")});out.push({t:bloomTime,label:"Pour 1",to:e1,note:P("A gentle, even pour — keep the water level steady, never let it run dry.","صبّة هادية ومتساوية — خلّي مستوى الماء ثابت، ولا تخلّيه يجف.")});out.push({t:bloomTime+40,label:"Pour 2",to:e2,note:P("Same calm pour again. Little and often keeps it even.","نفس الصبّة الهادية. شوي شوي يخلّيها متزنة.")});out.push({t:bloomTime+80,label:"Pour 3",to:totalWater,note:P("Last pour to full. One gentle swirl, then let it drain.","آخر صبّة للنهاية. دوّرة خفيفة، ثم خلّيها تصفّي.")});let prevE=0;return out.map(function(x){var pour=x.to-prevE;prevE=x.to;return{t:x.t,label:x.label,pour:pour,cum:x.to,note:x.note};});}if(goal.method==="osamah"){out.push({t:0,label:"Bloom",to:Math.round(totalWater*0.1429),note:"Saturate every ground, then swirl gently."});out.push({t:55,label:"Pour 1",to:Math.round(totalWater*0.6349),note:"Slow, steady spiral — take your time, about 25 seconds."});out.push({t:95,label:"Pour 2",to:Math.round(totalWater*0.7937),note:"Short, gentle pulse."});out.push({t:120,label:"Pour 3",to:totalWater,note:"Top up to full, then a gentle final swirl."});}else if(goal.method==="fifty"){out.push({t:0,label:"Bloom",to:bloomWater,note:"Saturate every ground, then swirl gently."});out.push({t:bloomTime,label:"Pour",to:totalWater,note:"One steady pour straight to full — simple and even. Give it a gentle swirl to settle."})}else if(goal.method==="hoffmann"){const sixty=Math.round(totalWater*0.6);out.push({t:0,label:"Bloom",to:bloomWater,note:"Saturate every ground, then swirl gently."});out.push({t:bloomTime,label:"Pour 1",to:sixty,note:P("This one is quick but steady — Hoffmann pours 60% at a good pace in even spirals. Keep the stream moving; a little agitation here is good.","هذه صبّة سريعة بطبيعتها — هوفمان يسكب 60% بإيقاع سريع نسبيًا بدوائر ثابتة. أبقِ التدفق مستمرًا؛ وقليل من التحريك هنا مطلوب.")});out.push({t:bloomTime+30,label:"Pour 2",to:totalWater,note:P("Now slower and gentler — top up to full by ~"+fmt(bloomTime+60)+", keeping the cone full. Then stir once each way and give a final swirl.","الآن أبطأ وألطف — كمّل حتى الامتلاء بحلول ~"+fmt(bloomTime+60)+" مع إبقاء المخروط ممتلئًا. ثم حرّك مرة بكل اتجاه وأعطِ تدويرة أخيرة.")})}else{const W=totalWater,big=goal.id==="brighter";const p1=Math.round(W*(big?0.24:0.16)),fortyTo=Math.round(W*0.4),n=(strengthId==="light"?1:(strengthId==="strong"?3:2));out.push({t:0,label:"Pour 1",to:p1,note:big?"Bigger first pour leans fruity. Swirl.":"Smaller first pour leans sweeter. Swirl."});out.push({t:bloomTime,label:"Pour 2",to:fortyTo,note:(goal.id==="brighter"?"A smaller second pour completes the 40% — the big first pour tips it toward acidity.":"A bigger second pour completes the 40% — the small first pour tips it toward sweetness.")});for(let i=1;i<=n;i++)out.push({t:bloomTime+45*i,label:"Pour "+(2+i),to:Math.min(Math.round(fortyTo+(W-fortyTo)*(i/n)),W),note:i===n?"Final pour to full volume.":"Strength-building pour."})}let prev=0;return out.map((s)=>{const pour=s.to-prev;prev=s.to;return{t:s.t,label:s.label,pour,cum:s.to,note:s.note}})}
