function actHuman(a){var M={"→ finer":P("one step finer","أنعم بدرجة"),"→ coarser":P("one step coarser","أخشن بدرجة"),"→ +2°C":P("2°C hotter","أسخن بدرجتين"),"→ -2°C":P("2°C cooler","أبرد بدرجتين"),"→ stronger":P("a stronger ratio","نسبة أقوى"),"→ lighter":P("a lighter ratio","نسبة أخف")};return M[a]||actLabel(a);}
