function today(){return new Date().toISOString().slice(0,10)}
function parseFin(v){v=String(v||"").trim();if(!v)return 0;var mm=/^([0-9]+):([0-5][0-9])$/.exec(v);if(mm)return +mm[1]*60+ +mm[2];if(!/^[0-9]+$/.test(v))return 0;if(v.length<=2)return +v*60;var ss=+v.slice(-2),mn=+v.slice(0,-2);return ss<60?mn*60+ss:0;}
