function retentionCalc(rec){var pe=document.getElementById("poured"),ce=document.getElementById("cupOut");var pv=parseFloat(pe&&pe.value);if(isNaN(pv))pv=rec.totalWater;var ov=parseFloat(ce&&ce.value);if(isNaN(ov))return{poured:pv,measured:false};if(ov>pv)return{poured:pv,measured:true,invalid:true,out:ov};var retained=Math.round(pv-ov),pct=Math.round(ov/pv*100),r=retained/rec.dose,fl=null,verdict="";if(rec.immersion){verdict="Immersion holds water differently — retention is less diagnostic here.";fl=null;}else if(r<1.3){verdict="Ran fast — usually grind too coarse or channeling (expect weak/sour).";fl="fast";}else if(r>2.7){verdict="Stalled — usually grind too fine or over-agitated (expect bitter/muddy).";fl="stall";}else{verdict="Healthy draw-down.";fl="ok";}return{poured:pv,measured:true,retained:retained,pct:pct,r:r,verdict:verdict,flow:fl,out:ov};}
