function renderAfterBrew(){var rec=buildRecipe(state);var p=document.getElementById("poured");if(p&&!p.value)p.placeholder=String(rec.totalWater);var info=retentionCalc(rec);var prevFt=(document.getElementById("finTime")||{}).value||"";var html='<div class="ab-f" style="margin-bottom:12px"><label class="ab-l">'+P("Finish time — just type digits: 425 = 4:25","وقت النهاية — اكتب الأرقام فقط: 425 = 4:25")+'</label><input id="finTime" class="txt" inputmode="numeric" placeholder="3:25" value="'+escName(prevFt)+'"></div>'+P('<div class="ab-exp">Target: ~'+rec.incupEst+'ml in cup (~'+rec.retainedEst+'ml held by the grounds).</div>','<div class="ab-exp">الهدف: ~'+rec.incupEst+'مل في الفنجان (~'+rec.retainedEst+'مل تحتجزها القهوة المطحونة).</div>');if(info.measured){if(info.invalid){html+=P('<div class="ab-verdict stall">That cannot be right — coffee in the cup ('+info.out+'ml) is more than the water poured ('+info.poured+'ml). Fill in Water poured with what you actually used (total water, including any ice), then re-check.</div>','<div class="ab-verdict stall">هذا غير ممكن — القهوة في الفنجان ('+info.out+'مل) أكثر من الماء المصبوب ('+info.poured+'مل). أدخِل الماء المصبوب بما استخدمته فعلًا (إجمالي الماء مع أي ثلج) ثم أعد الفحص.</div>');}else{html+=P('<div class="ab-you">You: '+info.out+'ml in cup · '+info.pct+'% · '+info.retained+'ml held</div>','<div class="ab-you">أنت: '+info.out+'مل في الفنجان · '+info.pct+'% · '+info.retained+'مل محتجز</div>')+'<div class="ab-verdict '+(info.flow||"")+'">'+tr(info.verdict)+(info.verdict?' <button class="thelp-btn" data-flowhelp="1">?</button>':'')+'</div>'+(flowHelpOpen&&info.verdict?flowHelp():'');}}var rr=document.getElementById("retResult");if(rr)rr.innerHTML=html;flow=(info.measured&&!info.invalid)?info.flow:null;var ftEl=document.getElementById("finTime");var ftRaw=(ftEl&&ftEl.value||"").trim();if(ftRaw){var fsec=parseFin(ftRaw)||NaN;if(!isNaN(fsec)&&fsec>30){var fv=(fsec<rec.finishLo-15)?"fast":((fsec>rec.finishHi+30)?"stall":"ok");flow=fv;var rr2=document.getElementById("retResult");if(rr2){rr2.innerHTML+=P('<div class="ab-you">Your finish '+fmt(fsec)+' — '+(fv==="ok"?"inside the window.":(fv==="fast"?"faster than target — grind is too coarse. Try 1–2 steps finer.":"slower than target — grind is too fine. Try 1–2 steps coarser."))+'</div>','<div class="ab-you">نهايتك '+fmt(fsec)+' — '+(fv==="ok"?"داخل النطاق.":(fv==="fast"?"أسرع من الهدف — الطحنة خشنة. جرّب درجة أو درجتين أنعم.":"أبطأ من الهدف — الطحنة ناعمة. جرّب درجة أو درجتين أخشن."))+'</div>');if(fv!=="ok"&&finApplied===ftRaw){rr2.innerHTML+='<div class="finapplied">'+P("Logged — grind moved 1 step. Brew again to check.","تم التسجيل — انضبطت الطحنة درجة. جرّب تحضيرة ثانية.")+'</div>';}else if(fv!=="ok"){rr2.innerHTML+='<button class="finapply" data-finapply="'+fv+'">'+P(fv==="fast"?"Log this — go 1 step finer":"Log this — go 1 step coarser",fv==="fast"?"سجّل هذا — درجة أنعم":"سجّل هذا — درجة أخشن")+'</button>';}}}}}
function brewEntry(rec,verdict,action){var info=retentionCalc(rec);var ftEl=document.getElementById("finTime");var ftv=(ftEl&&ftEl.value||"").trim();var ftSec=parseFin(ftv);var ret=(info.measured&&!info.invalid)?(info.pct+"% in cup"+(info.flow&&info.flow!=="ok"?" · "+({fast:"ran fast",stall:"stalled"}[info.flow]||""):"")):"";return{date:today(),grind:rec.grindNumber,grinder:state.grinder,temp:rec.temp,ratio:rec.ratioStr,taste:(taste?TASTE_LABELS[taste]:""),verdict:verdict||"",action:action||"",retention:ret,ft:(ftSec>30?ftSec:0),freshAt:rec.freshId};}
