function applyStatic(){document.body.className=(lang==="ar")?"ar":"";var _te=document.getElementById("tEyebrow");if(_te)_te.textContent=tr("Pour timer");var _tp2=document.getElementById("tPause");if(_tp2)_tp2.textContent=tr("Pause");var _tr2=document.getElementById("tReset");if(_tr2)_tr2.textContent=tr("Reset");var _ts2=document.getElementById("tSkip");if(_ts2)_ts2.textContent=tr("Skip");var _tc2=document.getElementById("tClose");if(_tc2)_tc2.textContent=tr("Close");var _by=document.getElementById("byline");if(_by){_by.innerHTML=P("Created by Abdulmajeed Mohammed Alwahieb","إعداد عبدالمجيد محمد الوهيّب")+' <span class="vertag">v'+APP_VERSION+'</span>';}var t=document.querySelector("#afterBrew .ab-title");if(t)t.textContent=tr("After the brew · weigh your cup (optional)");var labs=document.querySelectorAll("#afterBrew .ab-l");if(labs[0])labs[0].textContent=tr("Water poured (ml)");if(labs[1])labs[1].textContent=tr("Coffee in cup (ml)");var co=document.getElementById("cupOut");if(co)co.placeholder=tr("weigh it");var sn=document.getElementById("saveName");if(sn)sn.placeholder=tr("name this bag");var sc=document.getElementById("saveConfirm");if(sc)sc.textContent=tr("Save");}
function updateNav(){var n=document.getElementById("nav");var langBtn='<button class="navbtn" data-lang="1">'+(lang==="ar"?"EN":"عربي")+'</button>';var saved=(lang==="ar")?("★ المحفوظة ("+LIBRARY.length+")"):("★ Saved ("+LIBRARY.length+")");var body=(view==="build")?('<button class="navbtn" data-nav="library">'+saved+'</button><button class="navbtn" data-nav="machine">'+tr("Machine")+'</button><button class="navbtn" data-nav="learn">'+tr("Learn")+'</button>'):('<button class="navbtn" data-nav="build">'+tr("← Build")+'</button>');n.innerHTML=langBtn+body;}
function updateSaveBar(){var t=document.getElementById("saveToggle"),ah=document.getElementById("activeHint");var e=findBag(activeBagId);if(e){t.textContent=(lang==="ar")?("＋ سجّل هذا التحضير في "+e.name):("＋ Log this brew to "+e.name);ah.innerHTML=((lang==="ar")?"تعمل على ":"Working on ")+'<b>'+escName(e.name)+'</b> · <button id="newBag" class="linkbtn">'+tr("start a new bag")+'</button>';ah.style.display="block";}else{t.textContent=tr("★ Save this bag");ah.style.display="none";}}
function libFresh(en){try{var rd=en.state&&en.state.roastDate;if(!rd||!en.freshMin)return "";var days=Math.floor((Date.now()-Date.parse(rd))/86400000);var st,cl;if(days<en.freshMin){st=P("resting — too fresh","لسه طازج");cl="#3E8E8E";}else if(days<=en.freshMax){st=P("at its peak ✓","في القمة ✓");cl="#7BB661";}else if(days<=en.freshMax+21){st=P("getting tired","بدأ يتعب");cl="#E89A4B";}else{st=P("past its peak","تعدّى ذروته");cl="#C0563B";}return '<div class="lib-fresh" style="color:'+cl+'">'+P("Day ","يوم ")+days+" · "+st+'</div>';}catch(e){return "";}}
function renderLibrary(){var h='<div class="libtitle">'+tr("Your bags")+'</div>';h+='<div class="impwrap"><input id="impCode" class="txt" placeholder="'+tr("Paste an import code (CWS1...)")+'"><button id="impBtn" class="impbtn">'+tr("Import brew")+'</button></div>';if(!LIBRARY.length){h+='<div class="libempty">'+tr("No saved bags yet.<br>Dial one in, then tap “Tasted great ✓” or “Save this bag”.")+'</div>';}else{h+=LIBRARY.map(function(en,i){var H=(en.history||[]).slice(0,6);var hist=H.map(function(hh,j){var older=H[j+1];var outcome=tr(hh.taste||hh.verdict||"logged");var gtxt=String(hh.grind!==undefined?hh.grind:(hh.summary||""));if(older&&older.grind!==undefined&&hh.grind!==undefined&&String(older.grind)!==String(hh.grind)){var _n=parseFloat(hh.grind),_o=parseFloat(older.grind);gtxt=(!isNaN(_n)&&!isNaN(_o))?String(gtxt).replace(String(_n),_o+"→"+_n):gtxt;}var line='<span class="hist-grind">'+escName(gtxt)+'</span> → '+escName(outcome);if(hh.action)line+=' <span class="hist-act">'+escName(actLabel(hh.action))+'</span>';if(hh.retention)line+=' · '+escName(hh.retention);if(hh.freshAt==='aging')line+=' · '+P('aging','بدأ يتعب');else if(hh.freshAt==='stale')line+=' · '+P('past peak','تعدّى ذروته');var extras=[];if(hh.grind!==undefined){if(older&&older.temp!==undefined&&hh.temp!==older.temp)extras.push(older.temp+"→"+hh.temp+"°C");if(older&&older.ratio!==undefined&&hh.ratio!==older.ratio)extras.push(older.ratio+" → "+hh.ratio);}if(extras.length)line+=' · <span class="hist-chg">'+escName(extras.join(" · "))+'</span>';return '<div class="hist"><span class="hist-date">'+hh.date+'</span> '+line+'</div>';}).join('');return '<div class="lib-entry'+(en.id===activeBagId?' active':'')+'"><div class="lib-row"><div><div class="lib-name">'+escName(en.name)+'</div><div class="lib-sum">'+escName(en.summary||"")+(en.savedAt?' · '+en.savedAt:'')+'</div>'+libFresh(en)+'</div>'+(en.verdict?'<div class="lib-badge">'+escName(en.verdict)+'</div>':'')+'</div>'+(hist?'<div class="hist-wrap">'+hist+'</div>':'')+'<div class="lib-actions"><button class="lib-load" data-libload="'+i+'">'+tr("Load")+'</button><button class="lib-del" data-libdel="'+i+'">✕</button></div></div>'}).join('');}libraryView.innerHTML=h;}
var FUND=[
{t:"1 · Fresh coffee",d:"Whole beans roughly 1–4 weeks off roast, ground right before you brew. Stale or pre-ground coffee caps how good the cup can get, no matter your technique."},
{t:"2 · A scale",d:"Weighing your coffee and water is the most important step for a consistent result. 0.1 g resolution is ideal. Handy fact: 1 ml of water weighs 1 g — the millilitres in the recipe are exactly what your scale shows."},
{t:"3 · An even grind",d:"A burr grinder (not a blade) grinds evenly. Grind size is your main dial: finer pulls more (risking bitter), coarser pulls less (risking sour)."},
{t:"4 · Good water, just off boil",d:"Water is about 98% of the cup, so filtered or soft water helps a lot. Just off the boil for most roasts; a little cooler for dark."},
{t:"5 · Even pouring",d:"Wet all the grounds, then pour gently and evenly in circles. Sloppy pours channel water and extract unevenly."}
];
var CHAIN=[
{t:"Origin sets the bean",d:"Altitude and variety decide density and character. Roasters pick the roast level to flatter it: bright, dense coffees (Ethiopia, Kenya) usually go lighter to protect florals; softer, nutty ones (Brazil) take medium-dark gracefully. That is why you rarely meet a dark Gesha."},
{t:"Roast sets the clock",d:"Darker roasts are more porous and release their CO2 faster — they peak earlier and fade sooner. Light roasts trap gas in dense structure: they need longer rest and stay good longer. Process nudges the same clock — naturals usually want a few extra days."},
{t:"The date tells you where you are",d:"Day 20 can mean at its peak for a light washed coffee and past it for a dark roast. The number on the bag only means something combined with the roast and process."},
{t:"What the app does with this",d:"Your rest window is computed from roast and process, the freshness stage nudges grind and temperature, and the widget counts the days for you. Enter the roast date once — the chain runs itself."}
];
var PROCX=[{t:"Wet-hulled (Giling Basah)",d:"Sumatra’s method: the parchment is stripped while the bean is still wet and soft, then dried bare. It trades acidity for weight — earthy, herbal, syrupy cups. If the bag says Sumatra and tastes like a forest floor in the best way, this is why."},{t:"Decaf",d:"Caffeine is removed before roasting (Swiss Water, CO2, or EA methods). The processing leaves beans porous and fast-extracting, so decaf turns bitter easily — the app brews it a degree cooler, and coarser is the first fix if it still bites."},{t:"Co-fermented / Infused",d:"Co-fermented: fruit, spices, or specific yeasts are added to the fermentation tank so the flavor develops inside the seed. Infused: flavor is added after processing. Both give loud, unmistakable aromatics — and honest roasters disclose which one you are holding. Brewed slightly cooler so the added notes stay pleasant instead of harsh."}];
var BREWTIME=[
{t:"What it is",d:"The total time from the first drop of water to an empty, drained bed. You never control it directly — it is the result of your grind, your dose, and how you pour."},
{t:"Why it matters",d:"Water needs enough contact time to dissolve the sweetness out of the coffee. Brew time is the clearest sign of whether that contact actually happened."},
{t:"Way too fast",d:"Water raced through without extracting enough — expect a weak, sour, thin cup. Usual causes: grind too coarse, or channeling from uneven pouring."},
{t:"Way too slow",d:"Water sat on the coffee too long and kept stripping harsh compounds — expect bitter, dry, muddy. Usual causes: grind too fine, too much agitation, or a clogged filter."},
{t:"Fix the cause, not the clock",d:"You do not fix time directly — adjust the grind and time follows. Finishing near the expected time with an even bed is the real target."},
{t:"Taste is the judge",d:"A rough guide: within about 30 seconds of the recipe finish time is normal. If the time looked off but the cup tastes great — trust the cup. Time is a guide, taste decides."}
];
var PROC=[{t:"Washed",d:"The fruit is stripped off the seed, the beans ferment in water tanks to loosen the last sticky layer, then they are washed clean and dried. You taste the bean itself: clean, clear, brighter acidity."},{t:"Honey",d:"The skin comes off but some of the sticky fruit layer (the honey) stays on the bean while it dries. Halfway between washed and natural: more sweetness and body than washed, cleaner than natural."},{t:"Natural (dry)",d:"The whole cherry is dried in the sun with the fruit still on, then hulled. The bean absorbs fruit sugars for days — fruity, heavy, wine-like sweetness, and a more fragile bed when you brew."},{t:"Anaerobic",d:"Cherries ferment in sealed, oxygen-free tanks before drying. The controlled fermentation creates bold, unusual flavours — funky, boozy, intense. A little goes a long way; brew it gently."}];
var GLOSS=[
{t:"Extraction",d:"How much flavour you have dissolved out of the grounds. Too little tastes sour; too much tastes bitter; the middle is sweet and balanced."},
{t:"Extraction yield",d:"The percentage of the coffee mass that dissolved (target roughly 18–22%). Only truly known with a refractometer."},
{t:"Bloom",d:"The first small pour that wets the grounds and lets fresh coffee release trapped CO₂ before the main pour."},
{t:"Ratio",d:"Coffee to water, e.g. 1:16.7 means 16.7 g water per 1 g coffee. More water is weaker and cleaner; less is stronger and heavier."},
{t:"Agitation",d:"Stirring, swirling, and pour force. More agitation speeds extraction, but overdone it turns harsh."},
{t:"Swirl",d:"Hold the brewer or server and give it a gentle circular shake — like swirling juice in a glass — to level the bed and even out extraction. No spoon: stirring is a different, stronger move."},{t:"Channelling",d:"Water finding a fast path through cracks in the bed, so some grounds over-extract while others barely brew. Even pours prevent it."},
{t:"Draw-down",d:"How long the water takes to drain after your last pour. Fast usually means too coarse; slow or stalled means too fine."},
{t:"Degassing",d:"Fresh-roasted coffee releasing CO₂ for days after roast. Lots of gas makes a big bloom and can read sour."},
{t:"TDS / strength",d:"Total dissolved solids — how concentrated the brew is. Measured with a refractometer; the Strength setting is the everyday lever."},
{t:"Flash / Japanese iced",d:"Brewing hot straight onto ice to chill instantly and keep the aromatics. Different from cold brew."},
{t:"Cold brew",d:"Steeping grounds in cold water for many hours. Low acidity and smooth, but it loses the lively, aromatic notes."}
];
var KIT=[
{t:"Essential",d:"A scale (0.1 g), a burr grinder, and fresh coffee. These three decide most of your cup."},
{t:"Helps a lot",d:"A gooseneck kettle for pour control, plus a dripper and filters you like (V60, Kalita Wave, Chemex...)."},
{t:"Nice, not needed",d:"A temperature-control kettle, a timer (your phone is fine), and a refractometer (only if you want to measure — you can brew great coffee without one)."},
{t:"Honest advice",d:"An expensive dripper will not fix a bad grinder. If you are going to spend, spend on the grinder first."}
];
function learnSection(title,items){return '<div class="learn-sec"><div class="learn-h">'+tr(title)+'</div>'+items.map(function(it,ix){return '<div class="learn-item'+(ix===0?' pull':'')+'"><div class="learn-t">'+tr(it.t)+'</div><div class="learn-d">'+tr(it.d)+'</div></div>'}).join('')+'</div>';}
function grindMethodsData(){return [{n:P("Espresso","إسبريسو"),um:350},{n:P("Moka pot","موكا"),um:450},{n:P("AeroPress","إيروبريس"),um:550},{n:P("V60 / Pour-over","V60 / تقطير"),um:750},{n:P("Chemex","كيمكس"),um:950},{n:P("French press","فرنش برس"),um:1200},{n:P("Cold brew","كولد برو"),um:1500}];}
function grindStripHtml(){var ms=grindMethodsData();var cells="";ms.slice().reverse().forEach(function(m){var mm=m.um/1000;var d=2.2+(m.um/1500)*5.5;var W=46,H=96;var n=Math.min(110,Math.max(20,Math.round(W*H/(d*d*7))));var dots="";var seed=m.um;for(var i=0;i<n;i++){seed=(seed*9301+49297)%233280;var r1=seed/233280;seed=(seed*9301+49297)%233280;var r2=seed/233280;seed=(seed*9301+49297)%233280;var r3=seed/233280;var s2=d*(0.75+r3*0.6);var x=r1*90+2,y=r2*90+2;dots+='<span class="gsd" style="width:'+s2.toFixed(1)+'px;height:'+s2.toFixed(1)+'px;left:'+x+'%;top:'+y+'%"></span>';}cells+='<div class="gstrip-col"><div class="gstrip-patch">'+dots+'</div><div class="gstrip-l">'+m.n+'</div><div class="gstrip-u">'+m.um+'µ</div></div>';});return '<div class="gref"><div class="gref-head">'+P("GRIND REFERENCE","مرجع الطحن")+' · '+P("WHAT YOURS SHOULD LOOK LIKE","كيف يجب أن تبدو")+'</div><div class="gstrip">'+cells+'</div><div class="gstrip-ends"><span>◄ '+P("COARSE","خشن")+'</span><span>'+P("FINE","ناعم")+' ►</span></div></div>';}
function renderLearn(){learnView.innerHTML='<div class="libtitle">'+tr("Learn")+'</div><div class="libsub">'+tr("The basics that matter.")+'</div>'+learnSection("The five that matter most",FUND)+learnSection("Origin, roast, and the date — one chain",CHAIN)+learnSection("Why brew time matters",BREWTIME)+learnSection("How each process is made",PROC.concat(PROCX))+learnSection("Glossary",GLOSS)+learnSection("What you actually need",KIT)+grindStripHtml();}
function renderAll(){if(state.roastDate)state.days=daysFromIso(state.roastDate);var mv=document.getElementById("machineView");mv.style.display="none";if(view==="build"){buildView.style.display="";libraryView.style.display="none";learnView.style.display="none";renderInputs();renderCard();renderAfterBrew();updateSaveBar()}else if(view==="machine"){buildView.style.display="none";libraryView.style.display="none";learnView.style.display="none";mv.style.display="";renderMachine()}else if(view==="library"){buildView.style.display="none";libraryView.style.display="";learnView.style.display="none";renderLibrary()}else{buildView.style.display="none";libraryView.style.display="none";learnView.style.display="";renderLearn()}updateNav();applyStatic();persist()}

document.getElementById("nav").addEventListener("click",function(e){var lb=e.target.closest("[data-lang]");if(lb){lang=(lang==="ar")?"en":"ar";renderAll();return;}var b=e.target.closest("[data-nav]");if(!b)return;view=b.dataset.nav;taste=null;renderAll();});
