document.getElementById("afterBrew").addEventListener("input",function(e){if(e.target&&e.target.id==="finTime"){var v=e.target.value.replace(/[^0-9]/g,"");if(v.length>=3&&v.length<=4){var ss=v.slice(-2);if(+ss<60)e.target.value=v.slice(0,-2)+":"+ss;}}});
