document.getElementById("machineView").addEventListener("click",function(e){if(e.target.closest("[data-machcard]")){shareMachineCard();return;}var sb=e.target.closest(".seg-btn");if(sb&&(sb.dataset.key==="machine"||sb.dataset.key==="tempProfile")){state[sb.dataset.key]=sb.dataset.id;if(sb.dataset.key==="machine"){state.machineOn=true;if(sb.dataset.id==="xbloom"){if(state.grinder!=="xbloom"){state.grinderPrev=state.grinder;state.grinder="xbloom";}}else if(state.grinderPrev){state.grinder=state.grinderPrev;state.grinderPrev=null;}var ml=doseLimit();if(state.dose>ml)state.dose=ml;}persist();renderMachine();}});
document.getElementById("retResult").addEventListener("click",function(e){if(e.target.closest("[data-flowhelp]")){flowHelpOpen=!flowHelpOpen;renderAfterBrew();return;}var fap=e.target.closest("[data-finapply]");if(fap){var dir=fap.dataset.finapply;var _gg0=grinderById(state.grinder);var _cs0=(_gg0&&_gg0.micro&&_gg0.step)?((1/_gg0.micro)/_gg0.step):1;state.grindAdj=Math.round(((state.grindAdj||0)+(dir==="fast"?-_cs0:_cs0))*1000)/1000;var rec=buildRecipe(state);JOURNEY.push({ts:Date.now(),date:today(),taste:"finish",action:(dir==="fast"?"→ finer":"→ coarser"),grind:rec.grindNumber,temp:rec.temp});var bgf=activeBagId?findBag(activeBagId):null;if(bgf){if(!bgf.journey)bgf.journey=[];bgf.journey.push(JOURNEY[JOURNEY.length-1]);}finApplied=(function(){var _ft=document.getElementById("finTime");return _ft?(_ft.value||"").trim():"";})();persist();renderInputs();renderCard();renderAfterBrew();return;}});
card.addEventListener("click",function(e){if(e.target.closest("[data-why]")){whyOpen=!whyOpen;renderCard();return}if(e.target.closest("[data-tastehelp]")){tasteHelpOpen=!tasteHelpOpen;renderCard();return}if(e.target.closest("[data-setupgrinder]")){openGsetup();return}if(e.target.closest("[data-gcalopen]")){gcalOpen=true;renderCard();var gi=document.getElementById("gcalInput");if(gi)gi.focus();return}if(e.target.closest("[data-gcalreset]")){var g0=grinderById(state.grinder);if(g0){delete GRINDOFF[g0.id];persist();}gcalOpen=false;renderCard();return}if(e.target.closest("[data-gcalsave]")){var g1=grinderById(state.grinder);var gi2=document.getElementById("gcalInput");if(g1&&gi2){var rawTyped=parseFloat(gi2.value);if(!isNaN(rawTyped)){var typed=rawTyped;if(g1.micro){var wholeT=Math.floor(rawTyped);var clk=Math.round((rawTyped-wholeT)*10);if(clk>=g1.micro){wholeT+=1;clk=0;}typed=wholeT+clk/g1.micro;}var savedOff=GRINDOFF[g1.id];delete GRINDOFF[g1.id];var freshBook=buildRecipe(Object.assign({},state)).grindNumeric;if(savedOff!==undefined)GRINDOFF[g1.id]=savedOff;var newOff=Math.round((typed-freshBook)*1000)/1000;GRINDOFF[g1.id]=newOff;persist();}}gcalOpen=false;renderCard();return}if(e.target.closest("[data-sharecard]")){shareCard();return}if(e.target.closest("[data-share]")){doShare();return}var fap=e.target.closest("[data-finapply]");if(fap){var dir=fap.dataset.finapply;var rec=buildRecipe(state);JOURNEY.push({ts:Date.now(),date:today(),taste:"finish",action:(dir==="fast"?"→ finer":"→ coarser"),grind:rec.grindNumber,temp:rec.temp});var bgf=activeBagId?findBag(activeBagId):null;if(bgf){if(!bgf.journey)bgf.journey=[];bgf.journey.push(JOURNEY[JOURNEY.length-1]);}persist();renderCard();return}if(e.target.closest("[data-jundo]")){if(JOURNEY.length){JOURNEY.pop();var bgu=activeBagId?findBag(activeBagId):null;if(bgu&&bgu.journey&&bgu.journey.length)bgu.journey.pop();if(bgu&&bgu.history&&bgu.history.length)bgu.history.shift();persist();renderCard();}return}if(e.target.closest("[data-jreset]")){JOURNEY=[];var bg=activeBagId?findBag(activeBagId):null;if(bg)bg.journey=[];persist();renderCard();return}if(e.target.closest("[data-flowhelp]")){flowHelpOpen=!flowHelpOpen;renderAfterBrew();return}if(e.target.closest("[data-timer]")){startTimer();return}if(e.target.closest("[data-apply]")){var rec=buildRecipe(state);var ap=coachApply(taste,state,rec);if(ap&&ap.act){var bag=activeBagId?findBag(activeBagId):null;if(bag){bag.history=bag.history||[];bag.history.unshift(brewEntry(rec,"",ap.action));if(bag.history.length>20)bag.history.pop();}JOURNEY.push({ts:Date.now(),date:today(),taste:taste,flow:flow,grind:rec.grindNumber,temp:rec.temp,ratio:rec.ratioStr,action:ap.action});if(JOURNEY.length>30)JOURNEY.shift();if(bag)bag.journey=JOURNEY.slice();persist();ap.act();streak=(streak.sym===taste)?{sym:taste,n:streak.n+1}:{sym:taste,n:1};lastAction=ap.action;taste=null;renderAll();}return;}var tb=e.target.closest("[data-taste]");if(tb){var v=tb.dataset.taste;if(v==="great"){openSaveForm("Dialed in ✓");return}if(v!==taste)streak={sym:null,n:0};taste=(taste===v)?null:v;renderCard();return}});
libraryView.addEventListener("click",function(e){if(e.target&&e.target.id==="impBtn"){var fld=document.getElementById("impCode");var raw=((fld&&fld.value)||"");var pos=raw.indexOf("CWS1.");if(pos<0){showToast(P("No valid code found","لم يُعثر على رمز صالح"));return;}var b64=raw.slice(pos+5).split(/[^A-Za-z0-9+/=]/)[0];try{var imp=JSON.parse(decodeURIComponent(escape(atob(b64))));if(!imp||!imp.brewer||!imp.roast)throw 0;if(STATE_DEFAULTS)Object.assign(state,STATE_DEFAULTS);Object.assign(state,imp);if(!allGrinders().some(function(x){return x.id===state.grinder;}))state.grinder=GRINDERS[0].id;if(state.roastDate)state.days=daysFromIso(state.roastDate);activeBagId=null;JOURNEY=[];persist();view="build";renderAll();showToast(P("Brew imported — review, then save it","تم الاستيراد — راجع الوصفة ثم احفظها"));}catch(err){showToast(P("Could not read that code","تعذّرت قراءة الرمز"));}return;}var ld=e.target.closest("[data-libload]");if(ld){var en=LIBRARY[+ld.dataset.libload];if(en){try{Object.assign(state,JSON.parse(JSON.stringify(en.state)))}catch(e2){}var _known=allGrinders().some(function(x){return x.id===state.grinder;});if(!_known){var _lost=state.grinder;state.grinder=GRINDERS[0].id;showToast(P("That bag used a grinder this app no longer lists. Set yours up to get its own numbers.","هذا الكيس يستخدم مطحنة ما عادت موجودة. أضف مطحنتك لتطلع لك أرقامها."));}if(!state.roastDate)state.roastDate=isoFromDays(state.days||14);activeBagId=en.id;JOURNEY=(en.journey||[]).slice();persist();}taste=null;streak={sym:null,n:0};lastAction="";clearAfterBrew();view="build";renderAll();return}var dd=e.target.closest("[data-libdel]");if(dd){var di=+dd.dataset.libdel;if(LIBRARY[di]&&LIBRARY[di].id===activeBagId)activeBagId=null;LIBRARY.splice(di,1);persist();renderLibrary();updateNav();return}});
